const npcColors={officer:{skin:0xb98265,shirt:0x344c61,pants:0x263443,accent:0xd9c760},bandit:{skin:0x9b7058,shirt:0x4f392e,pants:0x292823,accent:0x9e302c},zombie:{skin:0x6a8b68,shirt:0x456349,pants:0x343b32,accent:0x9e1820}};
function makeNpc(type,x,z,arena=false){const root=new THREE.Group(),c=npcColors[type];root.position.set(x,floorY,z);npcGroup.add(root);
 const skin=new THREE.MeshStandardMaterial({color:c.skin,roughness:.88}),shirt=new THREE.MeshStandardMaterial({color:c.shirt,roughness:.86}),pants=new THREE.MeshStandardMaterial({color:c.pants,roughness:.9}),accent=new THREE.MeshStandardMaterial({color:c.accent,roughness:.72}),darkmat=new THREE.MeshStandardMaterial({color:0x202221,roughness:.5});
 const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.34,.48,5,10),shirt);torso.position.y=1.28;root.add(torso);const pelvis=new THREE.Mesh(new THREE.CapsuleGeometry(.26,.18,4,8),pants);pelvis.position.y=.79;root.add(pelvis);
 const head=new THREE.Mesh(new THREE.SphereGeometry(.25,18,14),skin);head.position.y=1.94;head.scale.set(.9,1.12,.9);root.add(head);
 const eyeMat=new THREE.MeshStandardMaterial({color:type==='zombie'?0xd5ff99:0x181a18,emissive:type==='zombie'?0x51672a:0x000000,emissiveIntensity:1});for(let s of [-1,1])sphere(root,s*.095,1.98,-.207,.034,eyeMat,[1,1,.5]);
 if(type==='officer'){const cap=cyl(root,0,2.19,0,.24,.25,.12,accent,12);box(root,0,2.16,-.12,.28,.035,.18,accent);box(root,-.18,1.39,-.305,.16,.17,.055,accent)}
 if(type==='bandit'){const mask=new THREE.Mesh(new THREE.SphereGeometry(.215,16,10),darkmat);mask.position.set(0,1.89,-.035);mask.scale.set(1,.48,1);root.add(mask);}
 if(type==='zombie'){head.rotation.z=-.12;const gash=new THREE.Mesh(new THREE.BoxGeometry(.13,.035,.018),mats.blood);gash.position.set(.1,2.03,-.219);root.add(gash)}
 const limbs=[];for(let s of [-1,1]){for(const kind of ['arm','leg']){let upper=kind==='arm'?1.34:.48;let len=kind==='arm'?.55:.64;let part=new THREE.Mesh(new THREE.CapsuleGeometry(kind==='arm'?.105:.13,len,4,8),kind==='arm'?shirt:pants);part.position.set(kind==='arm'?s*.45:s*.17,upper,kind==='arm'?0:0);part.rotation.z=kind==='arm'?s*.15:0;root.add(part);limbs.push({mesh:part,kind,side:s,detached:false})}}
 // utility belt / shoulder details
 if(type==='officer'){for(let s of [-1,1])box(root,s*.22,1.18,-.32,.08,.19,.04,accent)}
 if(type==='bandit')box(root,0,1.58,-.32,.38,.07,.06,accent);
 if(type==='zombie'){for(let s of [-1,1])sphere(root,s*.2,.8,-.25,.04,mats.blood,[.8,1,.4])}
 let tool=null;if(type==='officer'||type==='bandit'){tool=new THREE.Group();box(tool,0,0,0,.11,.14,.35,darkmat);box(tool,0,-.11,.07,.08,.22,.11,accent);tool.position.set(.48,1.13,-.24);root.add(tool)}
 return {root,type,hp:type==='zombie'?120:100,max:type==='zombie'?120:100,alive:true,hostile:type!=='officer',provoked:false,attack:0,walk:Math.random()*6,limbs,arena,tool,fallTimer:0};}
function spawnNpc(type){const a=Math.random()*Math.PI*2,r=mapName==='arena'?19:9;const x=player.x+Math.cos(a)*r,z=player.z+Math.sin(a)*r;const n=makeNpc(type,x,z,false);npcs.push(n);updateThreats();showToast((type==='zombie'?'INFECTED':type==='officer'?'OFFICER':'BANDIT')+' DEPLOYED');}
function spawnWave(){wave++;const count=Math.min(3+wave*2,22);for(let i=0;i<count;i++){const a=Math.random()*Math.PI*2,r=24+Math.random()*7;const n=makeNpc('zombie',Math.cos(a)*r,Math.sin(a)*r,true);npcs.push(n)}$('#wave-num').textContent=String(wave).padStart(2,'0');$('#wave-status').textContent='IN PROGRESS';showToast('WAVE '+String(wave).padStart(2,'0')+' — '+count+' INFECTED');updateThreats()}
function updateThreats(){$('#threat-count').textContent=String(npcs.filter(n=>n.alive&&n.type!=='officer'||n.alive&&n.provoked).length).padStart(2,'0')}
function showToast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');toastTimer=2.2}
function setAmmo(){const w=weapons[currentWeapon];if(w.type==='melee'){$('#ammo-now').textContent='∞';$('#ammo-max').textContent='∞'}else{$('#ammo-now').textContent=ammo;$('#ammo-max').textContent=w.mag}$('#weapon-title').textContent=w.name;$$('.slot').forEach((el,i)=>el.classList.toggle('selected',i===currentWeapon))}
function bloodBurst(pos,count=10){for(let i=0;i<count;i++){const mesh=new THREE.Mesh(new THREE.SphereGeometry(.035+Math.random()*.045,6,5),mats.blood);mesh.position.copy(pos);scene.add(mesh);effects.push({mesh,vel:new THREE.Vector3((Math.random()-.5)*4,Math.random()*4,(Math.random()-.5)*4),life:.5+Math.random()*.55})}}
function detachLimb(n,limb){if(limb.detached)return;limb.detached=true;n.root.remove(limb.mesh);const clone=new THREE.Mesh(limb.mesh.geometry,new THREE.MeshStandardMaterial({color:npcColors[n.type].skin,roughness:.9}));clone.position.set(n.root.position.x+limb.mesh.position.x,floorY+limb.mesh.position.y,n.root.position.z+limb.mesh.position.z);clone.rotation.copy(limb.mesh.rotation);scene.add(clone);effects.push({mesh:clone,vel:new THREE.Vector3((Math.random()-.5)*5,3+Math.random()*2,(Math.random()-.5)*5),life:2.2,part:true});bloodBurst(new THREE.Vector3(clone.position.x,clone.position.y,clone.position.z),13)}
function damageNpc(n,damage,headshot=false){if(!n.alive)return;n.hp-=damage;n.provoked=true;n.hostile=true;const pos=n.root.position.clone().add(new THREE.Vector3(0,headshot?1.95:1.2,0));bloodBurst(pos,headshot?12:7);if(n.type==='zombie'&&Math.random()<.30){const available=n.limbs.filter(l=>!l.detached);if(available.length)detachLimb(n,available[Math.floor(Math.random()*available.length)])}
 if(n.hp<=0){n.alive=false;kills++;$('#kill-count').textContent=String(kills).padStart(2,'0');$('#hitmarker').classList.add('on');hitTimer=.16;bloodBurst(pos,24);n.root.rotation.x=Math.PI/2;n.root.position.y=floorY-.1;if(n.type==='zombie'&&Math.random()<.5){let candidates=n.limbs.filter(l=>!l.detached);if(candidates.length)detachLimb(n,candidates[0])}showToast(n.type==='zombie'?'INFECTED DOWN':'TARGET DOWN');if(mapName==='arena')waveDelay=2.6;}
 updateThreats()}

